public void new()
{
    rentalListInternal = new List(Types::Class);
}

[SysAppCollection(classStr(FMActiveReservationListItem), "Reservation list")]
public List rentalList(List _value=rentalListInternal)
{
    rentalListInternal = _value;
    return rentalListInternal;
}

public static FMActiveReservationListPage getActiveReservations(SysAppEntityContext _entityContext, List _filterContextList)
{
    FMRental rentalTable;
    FMCustomer customerTable;
    FMActiveReservationListPage activeReservationListPage = new FMActiveReservationListPage();

    while select * from rentalTable
        join customerTable
        order by rentalTable.EndDate desc
        where rentalTable.Customer == customerTable.RecId
            && (rentalTable.State == FMReservationState::InProgress
                || rentalTable.State == FMReservationState::New
                || rentalTable.State == FMReservationState::ReadyForPickup)
    {
        FMActiveReservationListItem activeReservationListItem = new FMActiveReservationListItem();
        activeReservationListItem.populate(rentalTable);

        activeReservationListItem.customer(new FMCustomerRefGroup());
        activeReservationListItem.customer().populate(customerTable);

        activeReservationListPage.rentalList().addEnd(activeReservationListItem);
    }

    return activeReservationListPage;
}
